def normalizedParentTrace (v : LpHaarDyadicSetIndex → 𝕜)
    (P : LpHaarFiniteParent) : 𝕜 :=
  (unitIntervalMeasure.real P.set : 𝕜)⁻¹ * v ⟨P.level, P.atoms⟩

